config.code:
const raw = (input.contract_text || "").trim();
const title = (input.contract_title || "").trim() || "Untitled Contract";
const categories = ["auto-renewal", "unlimited-liability", "unilateral-changes", "data-sharing", "non-compete"];
if (!raw) {
  return { text: "", title, valid: false, reason: "contract_text is empty; no review possible.", categories };
}
const text = raw.replace(/\r\n/g, "\n").replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();
const words = text.split(/\s+/).length;
const contractLike = words >= 20 && /(agreement|party|parties|contract|terms|hereby|shall|clause|termination|liability|obligation)/i.test(text);
return {
  text,
  title,
  valid: contractLike,
  reason: contractLike ? "" : "Input does not appear to be a contract (too short or lacking contract language); returning an error report instead of findings.",
  categories
};

const norm = s => (s || "").toLowerCase().replace(/\s+/g, " ").trim();
const source = norm(nodes.normalize.output.text);
const results = nodes.scan_categories.output.results || [];
const all = [];
const dropped = [];
for (const r of results) {
  for (const f of (r && r.findings) || []) {
    if (f.quote && source.includes(norm(f.quote))) all.push(f);
    else dropped.push(f);
  }
}
const categories = nodes.normalize.output.categories || [];
const categories_checked = categories.map(c => {
  const n = all.filter(f => f.category === c).length;
  return { category: c, status: n > 0 ? "found (" + n + " findings)" : "not-found" };
});
const counts = { high: 0, medium: 0, low: 0 };
for (const f of all) counts[f.severity] = (counts[f.severity] || 0) + 1;
const severity_summary = "high: " + counts.high + ", medium: " + counts.medium + ", low: " + counts.low + "; total " + all.length + " findings" + (dropped.length ? "; " + dropped.length + " unverified quote(s) dropped" : "");
return {
  valid: nodes.normalize.output.valid,
  reason: nodes.normalize.output.reason,
  title: nodes.normalize.output.title,
  findings: all,
  categories_checked,
  severity_summary
};

config.prompt:
Apply the reviewer's feedback to this contract risk report.

CONTRACT TEXT (source of truth for verbatim quotes):
{{nodes.normalize.output.text}}

CURRENT FINDINGS:
{{nodes.compile.output.findings | json}}

REVIEWER FEEDBACK:
{{input.revision_feedback ?? nodes.reviewer_approval.output.comment ?? "No specific feedback; improve clarity and correctness of explanations and severities per the rubric."}}

SEVERITY RUBRIC: high = uncapped liability, perpetual/evergreen obligations, broad non-compete, or unrestricted data sharing/sale; medium = auto-renewal with short notice window, unilateral changes with notice but no consent; low = mitigated versions (liability cap exists, opt-out available, narrow scope).

Return the updated findings array. Keep every quote verbatim from the contract text. Every finding must include category (one of the five), severity (high/medium/low), quote, location_hint, plain-English explanation, and a concrete negotiation recommendation. Add or remove findings only as the feedback requires.
